function Assert-NegativeFixtureEntry([string]$case,$entry,[string]$root){
  function FNeed([bool]$ok,[string]$message){if(-not$ok){throw $message}}
  FNeed ($NegativeCases-contains$case) 'Negative active_cases contains unknown case.';FNeed ($null-ne$entry) "Negative missing case $case."
  foreach($field in $NegativeContracts[$case].fields){FNeed ($entry.PSObject.Properties.Name-contains$field) "Negative $case missing $field.";FNeed ($null-ne$entry.$field) "Negative $case has null $field."}
  FNeed (([string]$entry.path)-match'^[A-Za-z]:[\\/]') "Negative $case path must be absolute.";$full=[IO.Path]::GetFullPath([string]$entry.path);FNeed ($full.StartsWith($root+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)) "Negative $case path must be strictly beneath derived root."
